Accept a certified chain if and only if:
\begin{enumerate}
\item it \emph{validates}: the five checks of Section~\ref{sec:rules}
  --- certificate, signatures at declared versions, linkage, density,
  and the key-version discipline with the deployment's pin
  (\code{validCertifiedChain} plus the mode's key checks);
\item it is \emph{recent}: $\mathit{now} \le \mathit{tip.slot} + n$ on the
  verifier's own clock.

\begin{assumption}[Signatures]\label{ass:sig}
The model gives each participant a \emph{signing log}: at most one
block per slot, the one its honest signing path signed (\code{SigningLog}).

\begin{theorem}[Lockstep safety, per-generation census; Lean \code{lockstep\_client\_safety\_gen}]\label{thm:lock-gen}
Under the lockstep validator and the per-generation package --- honest signatures declare their grid window's counter; hash injectivity; the pin-free core signature surface; rent at most $\rho$ per window and, for every generation $j$ separately, at most $T$ seats whose generation-$j$ key is stolen; $\rho + T \le \fmax$ --- any two accepted chains with recent tips agree on the block $2n$ below each tip, and, through the parent-id chain, on their whole common prefix down to height $0$: no shared genesis is assumed (\code{lockstepGen\_recent\_genesis\_agreement}).
\end{theorem}

\begin{theorem}[Uniqueness, derived; Lean
\code{sigUnforgeableRecent\_of\_timed}]\label{thm:timed-uniq}
In any timed execution satisfying the EUF-CMA bridge and no back-dating,
Assumption~\ref{ass:sig}(c) holds for the projected log --- at every
recency window, the bar being a parameter the proof never uses.
\end{theorem}
